const items = $input.all();

const customers = items.map((item) => item.json);

const highRiskCustomers = customers.filter((c) => c.risk_level === "high");
const mediumRiskCustomers = customers.filter((c) => c.risk_level === "medium");
const lowRiskCustomers = customers.filter((c) => c.risk_level === "low");

return [
  {
    json: {
      priority_customers_count: customers.length,
      high_risk_count: highRiskCustomers.length,
      medium_risk_count: mediumRiskCustomers.length,
      low_risk_count: lowRiskCustomers.length,
      priority_customers: customers.slice(0, 10)
    }
  }
];

const items = $input.all();

const actions = items.map((item) => item.json);

const openActions = actions.filter((a) => a.status === "open");
const highPriority = actions.filter((a) => a.priority === "high");
const mediumPriority = actions.filter((a) => a.priority === "medium");
const lowPriority = actions.filter((a) => a.priority === "low");

return [
  {
    json: {
      sync_status: "success",
      synced_actions_count: actions.length,
      open_actions_count: openActions.length,
      high_priority_count: highPriority.length,
      medium_priority_count: mediumPriority.length,
      low_priority_count: lowPriority.length,
      synced_actions_sample: actions.slice(0, 5)
    }
  }
];

const config = $('Set Workflow Config').first().json;
const priorityPackage = $('Package Priority Customers').first().json;
const actionBoard = $json;

function formatDate(date) {
  return date.toISOString().slice(0, 10);
}

const today = new Date();
const reportDate = formatDate(today);

const githubOwner = config.github_owner || "Abderrahim-OUAHAB";
const githubRepo = config.github_repo || "RISKOPS-AI-COPILOT";
const language = config.language || "en";

const runTime = today.toISOString().slice(11, 16).replace(":", "");
const reportPath = `docs/reports/weekly-riskops-${reportDate}-${runTime}.md`;
const issueTitle = `Weekly RiskOps Briefing - ${reportDate} ${runTime}`;

const priorityCustomers = priorityPackage.priority_customers || [];
const actions = actionBoard.actions || [];
const summary = actionBoard.summary || {};

const aliasMap = {};
const letters = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";

function aliasCustomer(customerId) {
  if (!customerId) {
    return "Unknown Customer";
  }

  if (!aliasMap[customerId]) {
    const index = Object.keys(aliasMap).length;
    aliasMap[customerId] = `Customer ${letters[index] || index + 1}`;
  }

  return aliasMap[customerId];
}

function safeArray(value) {
  if (Array.isArray(value)) {
    return value;
  }

  if (!value) {
    return [];
  }

  return [String(value)];
}

const safeCustomers = priorityCustomers.slice(0, 10).map((customer) => {
  return {
    customer_alias: aliasCustomer(customer.customer_id),
    risk_score: Number(customer.risk_score || 0),
    risk_level: customer.risk_level || "unknown",
    confidence: customer.confidence ?? null,
    top_reasons: safeArray(customer.top_reasons || customer.reasons),
    recommended_actions: safeArray(customer.recommended_actions),
    next_best_action: customer.next_best_action || "Review customer risk",
    owner: customer.owner || "RiskOps Team",
    due_date: customer.due_date || "Not specified"
  };
});

const safeActions = actions.slice(0, 15).map((action, index) => {
  return {
    action_ref: `ACTION-${index + 1}`,
    customer_alias: aliasCustomer(action.customer_id),
    risk_level: action.risk_level || "unknown",
    priority: action.priority || "medium",
    action_label: action.action_label || "Review customer risk",
    reason: action.reason || "RiskOps recommendation",
    owner: action.owner || "RiskOps Team",
    due_date: action.due_date || "Not specified",
    status: action.status || "open",
    evidence_count: Number(action.evidence_count || 0),
    source: action.source || "risk_score"
  };
});

const highRiskCustomers = safeCustomers.filter((c) => c.risk_level === "high");
const mediumRiskCustomers = safeCustomers.filter((c) => c.risk_level === "medium");
const lowRiskCustomers = safeCustomers.filter((c) => c.risk_level === "low");

const overdueActions = safeActions.filter((action) => {
  if (!action.due_date || action.due_date === "Not specified") {
    return false;
  }

  const dueDate = new Date(action.due_date);
  return dueDate < today && action.status !== "completed";
});

const metrics = {
  priority_customers_count: Number(priorityPackage.priority_customers_count || safeCustomers.length),
  high_risk_count: Number(priorityPackage.high_risk_count || highRiskCustomers.length),
  medium_risk_count: Number(priorityPackage.medium_risk_count || mediumRiskCustomers.length),
  low_risk_count: Number(priorityPackage.low_risk_count || lowRiskCustomers.length),
  open_actions: Number(summary.open_actions || 0),
  in_progress_actions: Number(summary.in_progress || 0),
  completed_actions: Number(summary.completed || 0),
  cancelled_actions: Number(summary.cancelled || 0),
  overdue_actions: Number(summary.overdue || overdueActions.length),
  high_priority_actions: Number(summary.high_priority || 0)
};

return [
  {
    json: {
      workflow_name: "AI RiskOps GitHub Maintainer",
      report_date: reportDate,
      report_path: reportPath,
      issue_title: issueTitle,
      language: language,
      repository: {
        owner: githubOwner,
        name: githubRepo,
        version: "v1.5.0-n8n-github-automation"
      },
      metrics: metrics,
      top_priority_customers: safeCustomers,
      action_board: {
        summary: summary,
        actions: safeActions
      },
      automation_goal: {
        github_issue: true,
        markdown_report: true,
        no_sensitive_customer_ids: true,
        human_review_recommended: true
      },
      instructions_for_ai: [
        "Generate a professional GitHub maintenance report.",
        "Use only anonymized customer aliases.",
        "Do not expose customer_id values.",
        "Do not invent metrics.",
        "Focus on risk, actions, owners, due dates, and operational follow-up.",
        "Return structured JSON only."
      ]
    }
  }
];

