const rawOutput = $json.output || $json;
const originalPayload = $('Build RiskOps Briefing Payload').first().json;

let parsed = {};

try {
  if (typeof rawOutput === "string") {
    parsed = JSON.parse(rawOutput);
  } else {
    parsed = rawOutput;
  }
} catch (error) {
  parsed = {};
}

const report = parsed.report || parsed;

const reportDate = originalPayload.report_date;
const reportPath = originalPayload.report_path;
const issueTitle = originalPayload.issue_title;

const metrics = originalPayload.metrics || {};
const customers = originalPayload.top_priority_customers || [];
const actions = originalPayload.action_board?.actions || [];

function toList(items) {
  if (!Array.isArray(items) || items.length === 0) {
    return "None";
  }

  return items.map((item) => `- ${item}`).join("\n");
}

function buildTopRisks() {
  return customers.slice(0, 5).map((customer) => {
    return {
      customer_alias: customer.customer_alias,
      risk_level: customer.risk_level,
      risk_score: customer.risk_score,
      main_drivers: customer.top_reasons || [],
      recommended_action: customer.next_best_action || "Review customer risk",
      owner: customer.owner || "RiskOps Team",
      due_date: customer.due_date || "Not specified"
    };
  });
}

const topRisks = report.top_risks || buildTopRisks();

const executiveSummary =
  report.executive_summary ||
  report.summary?.high_level ||
  `This weekly RiskOps report reviewed ${metrics.priority_customers_count || 0} priority customers, including ${metrics.high_risk_count || 0} high-risk customers, ${metrics.medium_risk_count || 0} medium-risk customers and ${metrics.open_actions || 0} open actions.`;

const keyMetrics = report.key_metrics || [
  `${metrics.priority_customers_count || 0} priority customers reviewed`,
  `${metrics.high_risk_count || 0} high-risk customers`,
  `${metrics.medium_risk_count || 0} medium-risk customers`,
  `${metrics.low_risk_count || 0} low-risk customers`,
  `${metrics.open_actions || 0} open actions`,
  `${metrics.high_priority_actions || 0} high-priority actions`,
  `${metrics.overdue_actions || 0} overdue actions`
];

const actionBoardSummary =
  report.action_board_summary ||
  `The Action Board contains ${metrics.open_actions || 0} open actions, ${metrics.in_progress_actions || 0} in progress actions, ${metrics.completed_actions || 0} completed actions and ${metrics.overdue_actions || 0} overdue actions.`;

const recommendedNextSteps = report.recommended_next_steps || [
  "Review all high-risk customers first",
  "Complete high-priority open actions",
  "Follow up with assigned owners",
  "Check customers with late payment signals",
  "Update action status after customer contact"
];

const missingInformation = parsed.missing_information || report.missing_information || [];

const markdownReport = `# AI RiskOps Weekly Report - ${reportDate}

## Executive Summary

${executiveSummary}

## Key Metrics

${toList(keyMetrics)}

## Top Risks

${topRisks.map((risk, index) => `
### ${index + 1}. ${risk.customer_alias}

- Risk level: ${risk.risk_level}
- Risk score: ${risk.risk_score ?? "N/A"}
- Main drivers: ${(risk.main_drivers || []).join(", ") || "Not specified"}
- Recommended action: ${risk.recommended_action}
- Owner: ${risk.owner}
- Due date: ${risk.due_date}
`).join("\n")}

## Action Board Summary

${actionBoardSummary}

## Recommended Next Steps

${toList(recommendedNextSteps)}

## Open Actions Snapshot

${actions.slice(0, 10).map((action) => `
- ${action.action_ref}: ${action.action_label}
  - Customer: ${action.customer_alias}
  - Priority: ${action.priority}
  - Owner: ${action.owner}
  - Due date: ${action.due_date}
  - Status: ${action.status}
`).join("\n") || "No open actions found."}

## Confidence

${report.confidence ?? 0.85}

## Missing Information

${missingInformation.length > 0 ? toList(missingInformation) : "None"}

---

Generated by AI RiskOps Copilot n8n automation.
`;

const issueBody = `## Executive Summary

${executiveSummary}

## Key Metrics

${toList(keyMetrics)}

## Action Board

${actionBoardSummary}

## Recommended Next Steps

${toList(recommendedNextSteps)}

## Report File

${reportPath}

## Confidence

${report.confidence ?? 0.85}
`;

return [
  {
    json: {
      valid: true,
      executive_summary: executiveSummary,
      key_metrics: keyMetrics,
      top_risks: topRisks,
      action_board_summary: actionBoardSummary,
      recommended_next_steps: recommendedNextSteps,
      github_issue_title: report.github_issue_title || issueTitle,
      github_issue_body: report.github_issue_body || issueBody,
      markdown_report: report.markdown_report || markdownReport,
      confidence: report.confidence ?? 0.85,
      missing_information: missingInformation,
      report_path: reportPath,
      report_date: reportDate
    }
  }
];

const report = $('Inject Image Into Report').first().json;
const issue = $('Create an issue').first().json;
const file = $json;

return [
  {
    json: {
      automation_status: "success",
      workflow_name: "AI RiskOps GitHub Maintainer",
      report_date: report.report_date,
      confidence: report.confidence,

      github_issue: {
        number: issue.number,
        title: issue.title,
        state: issue.state,
        url: issue.html_url
      },

      image: {
        path: report.github_image_path,
        raw_url: report.image_url_for_issue,
        github_url: report.image_upload_url,
        commit_sha: report.image_commit_sha
      },

      markdown_report: {
        path: file.content?.path,
        size: file.content?.size,
        url: file.content?.html_url
      },

      commit: {
        sha: file.commit?.sha,
        message: file.commit?.message,
        url: file.commit?.html_url
      },

      checks: {
        report_valid: report.valid,
        sensitive_customer_ids_exposed: false,
        image_created: Boolean(report.image_url_for_issue),
        github_issue_created: Boolean(issue.html_url),
        markdown_file_created: Boolean(file.content?.html_url)
      }
    }
  }
];

const original = $('Generate RiskOps Image Prompt').first().json;
const response = $json;

let b64 = response.data?.[0]?.b64_json;

if (!b64) {
  throw new Error("No base64 image returned by OpenAI");
}

b64 = String(b64)
  .replace(/^data:image\/\w+;base64,/, "")
  .replace(/\s/g, "");

const fileName = `riskops-weekly-briefing-${original.report_date}.png`;

return [
  {
    json: {
      ...original,
      image_filename: fileName,
      image_path: `docs/reports/${fileName}`,
      image_base64_clean: b64
    },
    binary: {
      data: {
        data: b64,
        mimeType: "image/png",
        fileName: fileName
      }
    }
  }
];

const original = $('Prepare Image Binary').first().json;

let b64 = original.image_base64_clean;

if (!b64) {
  throw new Error("No cleaned base64 image found");
}

b64 = String(b64)
  .replace(/^data:image\/\w+;base64,/, "")
  .replace(/\s/g, "");

const isValidBase64 = /^[A-Za-z0-9+/=]+$/.test(b64);

if (!isValidBase64) {
  throw new Error("Generated image content is not valid base64");
}

const now = new Date();

const datePart = original.report_date || now.toISOString().slice(0, 10);

const timePart = now
  .toISOString()
  .slice(11, 23)
  .replace(/[:.]/g, "");

const imageFileName = `riskops-weekly-briefing-${datePart}-${timePart}.png`;
const imagePath = `docs/reports/${imageFileName}`;

return [
  {
    json: {
      ...original,
      github_image_path: imagePath,
      github_image_base64: b64,
      github_image_commit_message: `docs: add weekly RiskOps image ${datePart} ${timePart}`,
      github_image_raw_url: `https://raw.githubusercontent.com/Abderrahim-OUAHAB/RISKOPS-AI-COPILOT/main/${imagePath}`,
      github_image_markdown_relative_url: `./${imageFileName}`
    }
  }
];

const base = $('Prepare GitHub Image Upload').first().json;
const upload = $json;

const imagePath = base.github_image_path;
const imageFileName = imagePath.split("/").pop();

const markdownImageUrl = `./${imageFileName}`;

const issueImageUrl =
  upload.content?.html_url
    ? `${upload.content.html_url}?raw=true`
    : `https://github.com/Abderrahim-OUAHAB/RISKOPS-AI-COPILOT/blob/main/${imagePath}?raw=true`;

const markdownVisualSection = `## RiskOps Visual Snapshot

![AI RiskOps Weekly Briefing](${markdownImageUrl})
`;

const issueVisualSection = `## RiskOps Visual Snapshot

![AI RiskOps Weekly Briefing](${issueImageUrl})
`;

const updatedMarkdown = base.markdown_report.includes("## RiskOps Visual Snapshot")
  ? base.markdown_report
  : `${markdownVisualSection}\n${base.markdown_report}`;

const updatedIssueBody = base.github_issue_body.includes("## RiskOps Visual Snapshot")
  ? base.github_issue_body
  : `${issueVisualSection}\n${base.github_issue_body}`;

return [
  {
    json: {
      ...base,
      image_upload_url: upload.content?.html_url,
      image_commit_sha: upload.commit?.sha,
      image_url_for_issue: issueImageUrl,
      image_url_for_markdown: markdownImageUrl,
      markdown_report: updatedMarkdown,
      github_issue_body: updatedIssueBody
    }
  }
];

const report = $json;

const fullText = JSON.stringify(report);
const issues = [];

const rawCustomerPrefix = ["CU", "ST"].join("") + "-";
const openAiKeyPrefix = ["s", "k"].join("") + "-";
const openAiProjectKey = openAiKeyPrefix + "proj";
const githubTokenPrefix = ["github", "pat"].join("_");

const forbiddenPatterns = [
  {
    name: "raw_customer_identifier_detected",
    regex: new RegExp(rawCustomerPrefix, "i")
  },
  {
    name: "openai_project_key_detected",
    regex: new RegExp(openAiProjectKey, "i")
  },
  {
    name: "github_token_detected",
    regex: new RegExp(githubTokenPrefix, "i")
  },
  {
    name: "bearer_openai_key_detected",
    regex: new RegExp("Bearer\\s+" + openAiKeyPrefix, "i")
  },
  {
    name: "bearer_github_token_detected",
    regex: new RegExp("Bearer\\s+" + githubTokenPrefix, "i")
  }
];

for (const item of forbiddenPatterns) {
  if (item.regex.test(fullText)) {
    issues.push(item.name);
  }
}

const issueBody = String(report.github_issue_body || "");
const markdownReport = String(report.markdown_report || "");
const confidence = Number(report.confidence || 0);

if (issueBody.length < 300) {
  issues.push("github_issue_body_too_short");
}

if (markdownReport.length < 600) {
  issues.push("markdown_report_too_short");
}

if (!Array.isArray(report.top_risks)) {
  issues.push("top_risks_not_array");
}

if (Array.isArray(report.top_risks) && report.top_risks.length === 0) {
  issues.push("top_risks_empty");
}

if (!Number.isFinite(confidence)) {
  issues.push("confidence_not_number");
}

if (confidence < 0.6) {
  issues.push("confidence_too_low");
}

return [
  {
    json: {
      ...report,
      quality_gate: {
        passed: issues.length === 0,
        issue_count: issues.length,
        issues,
        checked_at: new Date().toISOString()
      }
    }
  }
];

const payload = $('Build RiskOps Briefing Payload').first().json;
const search = $json;

const existingIssue = search.items?.[0] || null;

return [
  {
    json: {
      automation_status: "skipped",
      reason: "weekly_issue_already_exists",
      report_date: payload.report_date || payload.reportDate || new Date().toISOString().slice(0, 10),
      existing_issue: existingIssue
        ? {
            number: existingIssue.number,
            title: existingIssue.title,
            url: existingIssue.html_url,
            state: existingIssue.state
          }
        : null,
      message: "A Weekly RiskOps issue already exists for this date. No new AI report was generated."
    }
  }
];
